function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){toast('浏览器存储不可用，本次进度只保留在内存');}}
function saveMeta(){try{localStorage.setItem(META_KEY,JSON.stringify(meta));}catch(e){}}
function load(){try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.screen)state={...state,...s,stats:{...EMPTY_STATS(),...(s.stats||{})},counts:{work:0,study:0,social:0,explore:0,trade:0,rest:0,...(s.counts||{})},busy:false};}catch(e){}
try{const m=JSON.parse(localStorage.getItem(META_KEY));if(m)meta={runs:[],achievements:[],...m};}catch(e){}
allocated=Object.values(state.stats||EMPTY_STATS()).reduce((a,b)=>a+b,0);
}
function toast(t){const el=$('#toast');el.textContent=t;el.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>el.style.display='none',3200);}
function go(screen){state.screen=screen;save();render();}
function world(){return WORLDS[state.worldIndex]||WORLDS[0];}
function factionName(i=0){const f=(world().factions||[])[i]||'当地势力';return f.split(/[，。；：,]/)[0].slice(0,12);}
function cal(){return {year:Math.floor(state.days/BASE_YEAR)+1,month:Math.floor((state.days%BASE_YEAR)/30)+1,day:state.days%30+1};}
function age(){return state.age+Math.floor(state.days/BASE_YEAR);}
function stage(){const a=age();if(a<7)return '幼年';if(a<13)return '童年';if(a<18)return '少年';if(a<30)return '青年';if(a<45)return '壮年';if(a<60)return '中年';return '晚年';}
function season(){return ['春','夏','秋','冬'][Math.floor((cal().month-1)/3)];}
function dateText(){const c=cal();return `第${c.year}年 ${c.month}月${c.day}日`;}
function cleanText(s){return String(s||'').replace(/。。+/g,'。').replace(/。\s*。/g,'。').replace(/\s+。/g,'。').replace(/([。！？])\s+/g,'$1').trim();}
function rank(){return ['E','D','C','B','A','S'][Math.min(5,Math.floor(state.importance/20))];}
function rate(offset=0){const d=Math.floor(Date.now()/86400000)+offset;const n=Math.sin(d/5+state.worldIndex*1.7)*.1+Math.sin(d*.71+state.worldIndex)*.05;return Math.max(.6,1+n+state.worldIndex%5*.025);}
function price(n){return Math.ceil(n*rate());}
function has(id){return state.talents.includes(id);}
function talent(id){return TALENTS.find(t=>t.id===id);}
function effect(){const e={income:1,cost:1,pill:1,risk:1,travel:1,trade:1,event:1,bond:1,intel:1,healthRegen:1,energy:1,time:1,workStat:'体魄',add:{life:0,health:0,coins:0,stats:{}}};for(const id of state.talents){const t=talent(id);if(!t)continue;if(t.mul)for(const k in t.mul)e[k]*=t.mul[k];if(t.workStat)e.workStat=t.workStat;if(t.add){e.add.life+=t.add.life||0;e.add.health+=t.add.health||0;e.add.coins+=t.add.coins||0;if(t.add.stats)for(const k in t.add.stats)e.add.stats[k]=(e.add.stats[k]||0)+t.add.stats[k];}}return e;}
function annualIncome(){const e=effect();return Math.floor((7000+state.career*1500+state.stats[e.workStat]*350)*e.income);}
function annualCost(){return Math.floor(LIVING_MONTH*12*effect().cost);}
function pillPrice(){return Math.ceil(PILL_BASE*Math.pow(1.8,state.pills)*effect().pill*rate());}
function pillYears(){const p=pillPrice(),net=annualIncome()-annualCost();if(net<=0)return '难以积累';return `${Math.ceil(p/net)}年`;}
