function hashText(t){let h=2166136261;for(let i=0;i<t.length;i++){h^=t.charCodeAt(i);h=Math.imul(h,16777619);}return Math.abs(h);}
function pickEnglish(seed){const un=ENGLISH_PACK.filter(x=>!meta.english.includes(x.id));const pool=un.length>=3?un:ENGLISH_PACK;const list=[...pool];const out=[];let h=hashText(String(seed)+state.worldIndex);while(out.length<3&&list.length){h=(h*1664525+1013904223)>>>0;const i=h%list.length;out.push(list.splice(i,1)[0]);}return out;}
function markEnglish(id){if(!state.englishThisLife.includes(id))state.englishThisLife.push(id);if(!meta.english.includes(id)){meta.english.push(id);saveMeta();}save();render(true);}
function englishCard(words){if(!words||!words.length)return '';return `<div class="card" style="border-color:#77b7fa44"><div class="row"><h3 class="cyan">本段英语 · English</h3></div><p class="small muted">场景里的三个词。点一下，把它留在这一生里。</p>${words.map(w=>`<button class="card english-card" style="width:100%;text-align:left;margin:9px 0;border-color:${meta.english.includes(w.id)?'#65e8d2':'#19444a'}" onclick="markEnglish('${w.id}')"><div class="row"><span class="english-word">${w.word}</span><span class="tag">${meta.english.includes(w.id)?'已记住':'点击记住'}</span></div><p class="english-zh">${w.zh}</p><p class="english-ex">${w.ex}</p></button>`).join('')}</div>`;}
