function conflicts(t){if(!t)return false;const sel=state.talents.map(talent);return (t.exclusive||[]).some(x=>state.talents.includes(x))||sel.some(x=>x&&(x.exclusive||[]).includes(t.id));}
function talentText(t){const sel=state.talents.includes(t.id),bad=conflicts(t);return `<button class="card talent ${sel?'selected':''}" ${bad&&!sel?'disabled':''} onclick="toggleTalent('${t.id}')"><div class="row"><h3 class="${t.r}">${t.name}</h3><span class="tag ${t.r}">${t.r} · ${t.school}</span></div><p>${t.desc}</p><div class="effect">${t.gain}</div><div class="cost">代价：${t.cost}</div>${t.evolve?`<div class="small muted">成长：${t.evolve.label}</div>`:''}${bad&&!sel?'<div class="small red">与已选天赋冲突</div>':''}</button>`;}
function attrs(){return `<div class="statrow">${[['智识',state.stats.智识,'#77b7fa'],['体魄',state.health,'#ee777c'],['精力',state.energy,'#e3bf74']].map(([n,v,c])=>`<div class="stat"><div class="statline"><span>${n}</span><b style="color:${c}">${v}</b></div><div class="bar"><i style="width:${Math.min(100,v*(n==='智识'?5:1))}%;background:${c}"></i></div></div>`).join('')}</div>`;}
function topBar(){return `<div class="top"><span class="brand">∞ 此世 / REBIRTH</span><div><button class="icon" onclick="showMeta()">档</button> <button class="icon" onclick="showGuide()">?</button> <button class="icon" onclick="showSettings()">⚙</button></div></div>`;}
function worldArt(){return `portraits/world-${String(state.worldIndex+1).padStart(2,'0')}.svg`;}
function render(keepScroll=false){const y=keepScroll?window.scrollY:0;const screens={wake,intro,setup,play};$('#app').innerHTML=topBar()+(screens[state.screen]||wake)();if(keepScroll){requestAnimationFrame(()=>window.scrollTo(0,y));}else{window.scrollTo(0,0);}}
function wake(){return `<div class="view splash"><div class="sigil">◉</div><div class="logo">INFINITE<br>REBIRTH</div><p class="subtitle">六十六个世界，六十六种人生。<br>这一次，不只成为传奇，也认真活过。</p><button class="btn primary" onclick="go('intro')">初始化神经连接</button>${meta.runs.length?`<button class="btn ghost" style="margin-top:12px;max-width:250px" onclick="showMeta()">轮回档案 · ${meta.runs.length}次人生</button>`:''}<p class="eyebrow" style="margin-top:30px">LOCAL FIRST · NO CLOUD SAVE</p></div>`;}
function intro(){return `<div class="view"><div class="eyebrow">SOUL ARCHIVE / 01</div><h1 class="title">录入此世的你</h1><p class="story">检测到宿主生命体征归零。<br>无限重生系统已完成绑定。<br><br>你将从一个孩子出生开始这一世：先有家人和童年，再长大、谋生、遇见人、老去。四维属性与天赋决定你手里有什么，怎么活由你决定。</p><div class="field"><label>姓名</label><input id="name" value="${esc(state.name)}" placeholder="输入姓名"></div><div class="field"><label>性别</label><select id="sex"><option ${state.sex==='男'?'selected':''}>男</option><option ${state.sex==='女'?'selected':''}>女</option><option ${state.sex==='其他'?'selected':''}>其他</option><option ${state.sex==='无性'?'selected':''}>无性</option></select></div><div class="field"><label>性格</label><input id="personality" value="${esc(state.personality)}"></div><div class="field"><label>外貌（用于原创画像与叙事）</label><textarea id="appearance" placeholder="例如：短发，眉眼安静，常穿洗得发白的工装">${esc(state.appearance)}</textarea></div><div class="card"><div class="row"><b>初始属性分配</b><span class="cyan" id="points">${20-allocated} 点可分配</span></div><p class="small muted">总计20点，每项1-10。属性影响事件选项、收入和风险，不决定一生上限。</p>${Object.keys(state.stats).map(k=>`<div class="attr" style="margin:12px 0"><span style="width:45px">${k}</span><button onclick="stat('${k}',-1)">−</button><output>${state.stats[k]}</output><button onclick="stat('${k}',1)">+</button><span class="small muted">${{智识:'研究/经营',体魄:'劳动/健康',魅力:'关系/声望',机缘:'机遇/风险'}[k]}</span></div>`).join('')}</div><button class="btn primary" onclick="confirmIntro()">确认灵魂档案</button></div>`;}
function syncIntroFields(){const n=$('#name'),sx=$('#sex'),ap=$('#appearance'),p=$('#personality');if(n)state.name=n.value;if(sx)state.sex=sx.value;if(ap)state.appearance=ap.value;if(p)state.personality=p.value;}
function stat(k,d){syncIntroFields();const v=state.stats[k]+d;if(v<1||v>10)return;if(d>0&&allocated>=20)return;allocated+=d;state.stats[k]=v;render(true);}
function confirmIntro(){state.name=$('#name').value.trim()||'无名旅人';state.sex=$('#sex')?.value||state.sex;state.age=0;state.appearance=$('#appearance').value;state.personality=$('#personality').value;state.baseStats={...state.stats};if(!candidateIndices.length)candidateIndices=Array.from({length:66},(_,i)=>i).sort(()=>Math.random()-.5).slice(0,6);state.screen='setup';setupStep=0;save();render();}
function setup(){return `<div class="view"><div class="eyebrow">WORLD CONNECTION / 02</div><h1 class="title">为此生做准备</h1><div class="tabs">${['开局模式','世界接入','天赋构筑','接入凭证'].map((t,i)=>`<button class="tab ${setupStep===i?'active':''}" onclick="step(${i})">${t}</button>`).join('')}</div>${[modeSetup,worldSetup,talentSetup,exportSetup][setupStep]()}</div>`;}
function step(i){setupStep=i;render();}
function modeSetup(){return `<div class="card"><h3>全新攻略者</h3><p class="small muted">以普通身份从零开始。收入、健康、寿命和人物关系都遵循本世界规则。</p><span class="tag cyan">当前模式</span></div><div class="notice">无初始神装。你能带走的是属性、天赋与选择，而不是无限资源。高稀有天赋不是免费午餐。</div><button class="btn primary" onclick="step(1)">选择世界</button>`;}
function worldCardsHTML(){const list=WORLDS.map((w,i)=>({...w,i})).filter(w=>!search||w.name.includes(search)||w.category.includes(search)||(w.theme||'').includes(search));const ids=search?list.map(w=>w.i):(candidateIndices.length?candidateIndices:list.map(w=>w.i));return ids.map(i=>WORLDS[i]).filter(Boolean).map(w=>{const i=WORLDS.indexOf(w);return `<div class="card"><span class="world-number">WORLD ${String(i+1).padStart(2,'0')}</span><div class="row"><h3 class="cyan">${w.name}</h3><span class="tag">${w.category}</span></div><p class="small">${esc(w.theme||w.civilization||'')}</p><p class="small muted">${esc(w.era||'')} · 货币：${w.currency} · 起始身份：${esc(w.identity||'')}</p><div class="row"><button class="btn ghost" style="width:auto" onclick="showDossier(${i})">十六维档案</button><button class="btn primary" style="width:auto" onclick="chooseWorld(${i})">锚定此界</button></div></div>`;}).join('');}
function onWorldSearch(value){search=value;candidateIndices=[];const box=$('#world-list');if(box)box.innerHTML=worldCardsHTML();}
function showAllWorlds(){candidateIndices=WORLDS.map((_,i)=>i);search='';render(true);}
function worldSetup(){return `<div class="field"><label>检索66个独立文明</label><input oninput="onWorldSearch(this.value)" value="${esc(search)}" placeholder="世界名 / 类型 / 主题"></div><button class="btn" onclick="randomWorld()">⚄ 随机探测位面（6选1）</button><button class="btn ghost" onclick="showAllWorlds()">浏览全部66界</button><div id="world-list">${worldCardsHTML()}</div>`;}
function randomWorld(){candidateIndices=Array.from({length:66},(_,i)=>i).sort(()=>Math.random()-.5).slice(0,6);search='';setupStep=1;save();render();toast('已探测6个位面，可以查看档案后锚定');}
function chooseWorld(i){state.worldIndex=i;state.identity=world().identity||'流浪者';state.talents=[];state.roll=0;state.pools=[];state.coins=START_COINS;setupStep=2;save();render();}
function drawable(){return TALENTS.filter(t=>!t.hidden);}
function rollTalents(){state.roll++;const rarities=state.roll%5===0?['C','B','A','S','SSS','SS','UR']:['C','C','B','B','A','S'];const picked=[];for(const r of rarities){const pool=drawable().filter(t=>t.r===r&&!state.talents.includes(t.id)&&!conflicts(t)&&!picked.includes(t.id));if(pool.length)picked.push(pool[Math.floor(Math.random()*pool.length)].id);}state.pools=[...new Set([...state.talents,...picked])].slice(0,8);save();render(true);}
function toggleTalent(id){if(state.talents.includes(id))state.talents=state.talents.filter(t=>t!==id);else{const t=talent(id);if(conflicts(t))return toast('与已选天赋冲突，请先取消另一项');if(state.talents.length<3)state.talents.push(id);else return toast('本轮最多携带3个天赋，先取消一个再替换');}save();render(true);}
function talentSetup(){return `<div class="card"><div class="row"><h3 class="cyan">${world().name} · ${state.identity}</h3><span class="tag">${world().currency}</span></div><p class="small">${esc(world().theme||world().civilization||'')}</p><p class="small muted">${esc(world().time||'')}</p><p class="small muted">${esc(world().space||'')}</p><button class="btn ghost" onclick="showDossier(${state.worldIndex})">打开完整世界档案</button></div><div class="notice">选择3个天赋。普通天赋有稳定谋生路线；SSS/UR带寿限、收入或健康代价。天赋达到条件会成长，且存在互斥组合。</div><button class="btn primary" onclick="rollTalents()">抽取构筑池 · 第${state.roll+1}次</button><p class="small muted">已选 ${state.talents.length}/3 · 重抽保留已选项 · 第5抽出现S/SS/SSS/UR候选</p>${state.pools.map(id=>talentText(talent(id))).join('')}<button class="btn primary" ${state.talents.length!==3?'disabled':''} onclick="step(3)">确认构筑</button>`;}
function exportSetup(){return `<div class="card"><h3>${esc(state.name)} · 从 0 岁开始</h3><p>${world().name} / ${state.identity}</p><p class="small muted">${state.talents.map(id=>talent(id)?.name).join(' · ')||'尚未选择天赋'}</p><hr class="divider"><p class="small">初始资金 ${START_COINS} ${world().currency}<br>自然寿限 100 岁<br>续命药 ${PILL_BASE.toLocaleString()} ${world().currency} 起，之后每颗×1.8</p><p class="small muted">按初始工作收入，第一颗药大约需要数年经营；天赋成长、经商和冒险会改变这个速度。</p></div><button class="btn primary" ${state.talents.length!==3?'disabled':''} onclick="begin()">以此身份，开始一生</button>`;}
function resetLife(){state.days=0;state.lifeLimit=100;state.coins=START_COINS;state.health=100;state.energy=100;state.importance=0;state.career=1;state.reputation=0;state.bond=0;state.flags=[];state.counts={work:0,study:0,social:0,explore:0,trade:0,rest:0};state.recentEvents=[];state.events=[];state.chronicle=[];state.inventory={};state.pills=0;state.location=0;state.deceased=false;state.runRecorded=false;state.lastOutcome=null;state.result=null;state.relationships=[];state.relationNote='';state.englishThisLife=[];state.scene=null;state.dialog=[];state.sceneTurns=0;state.sceneStats={warmth:0,resolve:0,honesty:0};state.monthSummary=null;state.mainStage=0;state.employed=false;state.salary=0;state.openingDone=false;state.jobDone=false;state.study=false;state.lifePath='';state.memories=[];state.emotions={喜:30,怒:20,哀:20,惧:20,爱:30,恶:15,欲:30};state.familySeeded=false;state.seenScenes=[];state.stageSeen={};state.chainQueue=[];state.recentScenes=[];state.lastChapterAge=undefined;state.englishChapters=[];state.englishSeen=[];state.pension=0;state.artUrl='';state.achievements=[];state.stats={...(state.baseStats||EMPTY_STATS())};}
function begin(){resetLife();const e=effect();state.coins=Math.max(60,START_COINS+e.add.coins);state.lifeLimit=100+e.add.life;state.health=Math.max(20,100+e.add.health);for(const k in e.add.stats)state.stats[k]=Math.max(1,Math.min(20,state.stats[k]+e.add.stats[k]));if(has('debt'))state.flags.push('debt');if(has('gambit'))state.flags.push('孤注者');if(has('world'))state.flags.push('被注视者');state.occupation='无业游民';if(age()>=16)ensureRelationships();state.result=null;state.currentEvent=null;state.scene=nextMonthScene();state.dialog=sceneIntro(state.scene);state.screen='play';page='month';save();render();}

const NPC_NAMES=['沈砚','苏晚','陆青','顾棠','江雪','白榆','闻笙','鹤汀','阿岚','叙川','林见','宁舟','程野','温梨','谢回','叶弥','宋知','许照','顾浔','陆遥'];
const NPC_ROLES=['同路行商','旧书店主','夜巡人','游方医者','工坊学徒','渡口船工','抄书人','酒馆老板'];
const NPC_TRAITS=['说话很慢，但记得别人随口提过的小事。','嘴上不饶人，遇到麻烦却总是第一个到场。','对世界有不合时宜的好奇心。','把体面看得比命重，却愿意为朋友破例。','擅长在沉默里听懂弦外之音。','习惯把危险说成玩笑，怕别人替自己担心。'];
const NPC_DESIRES=['想离开这里，去看看地图外的世界。','想守住一份快被时代忘掉的手艺。','想弄清一桩被所有人默认不存在的旧事。','想让家人过上好日子，哪怕自己被人看不起。','想找到一个愿意听自己说完的人。','想证明普通人也配拥有自己的名字。'];
const SPARKS=['你们在雨檐下躲了很久，谁都没有先开口。后来他/她递来半块热饼，说：下次别站在雨里。','你发现对方也记得你上次随口提过的小事。那一瞬间，比任何誓言都更像“被看见”。','你们为一件小事争得面红耳赤，最后却同时笑了。关系的裂缝没有扩大，反而露出了里面的光。','对方把一件不轻易给人看的东西交到你手里，说：先替我保管。你知道这不是随手托付。','分别时，他/她走出几步又回头，像要说什么，最终只挥了挥手。你站在原地很久。'];
function ensureRelationships(){if(state.relationships&&state.relationships.length)return;const names=[...NPC_NAMES];const start=state.worldIndex%names.length;state.relationships=[0,1,2].map(i=>{const name=names[(start+i*5)%names.length];const role=NPC_ROLES[(state.worldIndex+i*3)%NPC_ROLES.length];const affinity=i===0?22:Math.floor(Math.random()*8);const trust=i===0?18:Math.floor(Math.random()*5);return {id:'npc'+i,name,role,trait:NPC_TRAITS[(state.worldIndex+i)%NPC_TRAITS.length],desire:NPC_DESIRES[(state.worldIndex+i*2)%NPC_DESIRES.length],affinity,trust,romance:false,history:[]};});}
function relationStage(r){const score=(r.affinity+r.trust)/2;if(r.romance&&score>=78&&r.affinity>=80)return '恋人';if(score>=65)return '知己';if(score>=42)return '好友';if(score>=20)return '相识';return '陌生';}
function relationLine(){const rs=state.relationships||[];if(!rs.length)return '你还没有认真认识谁。';const best=[...rs].sort((a,b)=>(b.affinity+b.trust)-(a.affinity+a.trust))[0];return `${best.name}（${best.role}） · ${relationStage(best)} · 好感${best.affinity} 信任${best.trust}`;}
function relationNote(text){state.relationNote=text;save();}
function meetSomeone(){if(state.relationships.length>=6)return toast('你已经认识了很多重要的人');if(state.coins<100)return toast('至少需要100本世界币作为路费');state.coins-=100;advance(90);if(state.deceased){page='event';render();return;}const i=state.relationships.length;const name=NPC_NAMES[(state.worldIndex+i*5+2)%NPC_NAMES.length];state.relationships.push({id:'npc'+Date.now(),name,role:NPC_ROLES[(state.worldIndex+i)%NPC_ROLES.length],trait:NPC_TRAITS[(state.worldIndex+i*2)%NPC_TRAITS.length],desire:NPC_DESIRES[(state.worldIndex+i)%NPC_DESIRES.length],affinity:8,trust:5,romance:false,history:[]});state.relationNote=`你在${world().locations?.[state.location]?.name||'路上'}遇见了${name}。${name}说：${NPC_TRAITS[(state.worldIndex+i)%NPC_TRAITS.length]}`;page='relation';save();render();}
function talkTo(id){const r=state.relationships.find(x=>x.id===id);if(!r||state.deceased)return;advance(90);if(state.deceased){page='event';render();return;}r.affinity=Math.min(100,r.affinity+6+Math.floor(state.stats.魅力/3)+Math.floor(Math.random()*4));r.trust=Math.min(100,r.trust+3+Math.floor(state.stats.机缘/4));r.history.push('交谈');state.relationNote=`${r.name}听你说完近来的事，没有急着给建议。你们在${world().locations?.[state.location]?.name||'长街'}坐到天色变暗。`;checkRelationships();save();render(true);}
function shareWith(id){const r=state.relationships.find(x=>x.id===id);if(!r||state.deceased)return;if(state.coins<200)return toast('至少需要200本世界币');state.coins-=200;advance(180);if(state.deceased){page='event';render();return;}r.affinity=Math.min(100,r.affinity+11+Math.floor(state.stats.魅力/4));r.trust=Math.min(100,r.trust+8);r.history.push('共同经历');state.relationNote=`你和${r.name}一起去了${world().locations?.[(state.location+1)%4]?.name||'城外'}。路上遇到一点麻烦，你们都没有丢下对方。回来的路上，${r.name}说：下次还来。`;checkRelationships();save();render(true);}
function confess(id){const r=state.relationships.find(x=>x.id===id);if(!r||state.deceased)return;if(relationStage(r)!=='知己')return toast('至少要到知己阶段，才适合说这句话');if(r.affinity<80||r.trust<65)return toast('你们之间还差一点信任');advance(120);if(state.deceased){page='event';render();return;}r.romance=true;r.affinity=Math.min(100,r.affinity+8);r.history.push('确认关系');state.relationNote=`你把话说出口。${r.name}沉默了很久，最后没有回答“好”或“不好”，只是把手放在你手心里。你们决定一起走一段路，看看能走到哪里。`;checkRelationships();checkAchievements();save();render(true);}
function checkRelationships(){for(const r of state.relationships){const stage=relationStage(r);if(stage==='知己'&&!r.history.includes('知己')){r.history.push('知己');state.chronicle.unshift({year:cal().year,title:`遇见知己：${r.name}`,detail:`${r.name}成为你在这个世界真正理解你的人。`});toast(`关系变化：${r.name}成为知己`);}if(stage==='恋人'&&!r.history.includes('恋人')){r.history.push('恋人');state.chronicle.unshift({year:cal().year,title:`有人同行：${r.name}`,detail:`你和${r.name}决定以恋人的身份继续生活。`});toast(`关系变化：${r.name}成为恋人`);}}}

const c=(id,title,desc,hint,bonus)=>({id,title,desc,hint,bonus});
const EVENTS=[
{id:'arrival',stage:['少年','青年','壮年','中年','晚年'],weight:12,title:'落脚',text:()=>`你带着并不丰厚的行囊，在${world().name}暂时住下。${world().dailyLife||world().civilization||'这里的人靠手艺与关系谋生'}。房东提醒你：在这个世界，普通人要先学会养活自己，再谈改变命运。`,choices:[c('work','先找一份工','用工钱换一个安稳的落脚处。','工作 · 年收入'),c('study','摸清当地规则','向邻居和匠人请教，少走弯路。','智识+ · 少量收入'),c('social','认识邻居','先记住彼此的名字。','羁绊+')]},
{id:'first_job',stage:['青年','壮年'],weight:10,when:s=>s.counts.work===0,title:'第一份差事',text:()=>`工头看了看你的手，又看了看你的眼睛，最终把一件不算轻松的活交给你。${world().economy||''} 这份工作不会让人一夜暴富，但足以证明你能在这个世界留下。`,choices:[c('work','把活干完','按约定完成工作，拿到第一笔工钱。','工作 · 职业成长'),c('study','边做边学','向老工人请教这门手艺的门道。','智识+ · 收入较少'),c('trade','打听行情','看看这门生意还能怎么做。','需要本金 · 经商')]},
{id:'old_book',stage:['青年','壮年','中年'],weight:8,when:s=>s.stats.智识>=6,title:'旧册里的世界',text:()=>`你在旧书摊翻到一本没有署名的札记，里面记录着${world().name}的${world().tech||'技艺'}与${world().beliefs||'民间规矩'}。书页边缘有人用铅笔写着：不要相信最简单的答案。`,choices:[c('study','读完它','花时间整理其中的知识。','智识+ · 重要度+'),c('explore','按图索骥','去找札记里提到的地点。','探索 · 风险'),c('social','寻找作者','向旧书摊主打听这本书的来历。','羁绊+')]},
{id:'market',stage:['少年','青年','壮年','中年','晚年'],weight:9,title:'集市上的争执',text:()=>`集市里有人因一笔小账争得面红耳赤。围观的人越来越多，却没有谁愿意先站出来。你注意到其中一方的手在发抖，另一方则不断看向${factionName(0)}的方向。`,choices:[c('social','先劝开两人','不让事情在众目睽睽下失控。','羁绊+ · 声望+'),c('study','查清账目','用纸笔和证词还原真相。','智识+ · 重要度+'),c('rest','离开这里','这不是你必须承担的事。','恢复 · 无收益')]},
{id:'illness',stage:['青年','壮年','中年','晚年'],weight:7,when:s=>s.health<70,title:'病中',text:()=>`你病了一场。高烧让你分不清窗外的雨声和记忆里的声音。${world().risks||''} 在这种地方，普通人最先失去的不是勇气，而是照顾自己的时间。`,choices:[c('rest','停下来养病','把这一年留给身体。','恢复健康 · 不赚钱'),c('work','带病上工','生活不会因为发烧而暂停。','收入 · 健康风险'),c('study','读点医书','试着弄懂自己的身体。','智识+ · 少量恢复')]},
{id:'debt',stage:['壮年','中年','晚年'],weight:12,when:s=>s.flags.includes('debt')||s.coins<800,title:'旧债上门',text:()=>`一个陌生人带着账本找上门。他没有大喊大叫，只把日期、数目和担保人的名字一项项念给你听。${world().order||'这里的秩序并不总站在弱者一边。'} 你意识到，这笔债不会因为换一个城市就消失。`,choices:[c('work','先还一部分','用劳动换取喘息的时间。','还款 · 职业成长'),c('trade','做一笔快生意','用剩下的钱博一次周转。','经商 · 有亏损风险'),c('explore','离开这里','去更远的地方寻找机会，也留下更多债务。','探索 · 风险')]},
{id:'apprentice',stage:['壮年','中年'],weight:8,when:s=>s.career>=3,title:'有人想拜你为师',text:()=>`一个年轻人站在门口，手里攥着一份写得歪歪扭扭的拜师礼单。他说自己听过你的名字，也听过别人对你的评价。你忽然发现，自己已经不再是那个刚来到${world().name}的人。`,choices:[c('study','教他真本事','把自己踩过的坑讲清楚。','智识+ · 声望+'),c('social','先留下他','让人有饭吃，再谈手艺。','羁绊+ · 生活成本略增'),c('work','继续忙自己的','你还没有余力照顾另一个人的命运。','收入 · 声望+')]},
{id:'letter',stage:['青年','壮年','中年','晚年'],weight:9,when:s=>s.bond>=30,title:'一封旧信',text:()=>`你收到一封没有寄件地址的信。信里只有几行字，提到你们共同经历过的一件小事，最后写着：如果你还在这座城市，记得来看看。落款是你几乎快要忘记的名字。`,choices:[c('social','赴约','有些人值得你放下手里的事。','羁绊+ · 恢复'),c('work','先处理生计','把信收进抽屉，等忙完这一阵。','收入 · 羁绊-'),c('rest','给自己一天','读信，做饭，想起从前。','恢复 · 重要度+')]},
{id:'migration',stage:['青年','壮年','中年'],weight:6,when:s=>s.days>=BASE_YEAR*3,title:'搬迁的季节',text:()=>`房租涨了，或是一份新工作出现在别处。${world().space||''} 你开始认真考虑离开熟悉的街区。这个决定不会改变世界，却会改变你每天醒来看到的东西。`,choices:[c('explore','搬去新的地方','带着行李去另一片区域。','更换地点 · 花费'),c('work','留在原地多接活','熟悉的地方也有熟悉的机会。','收入 · 声望+'),c('social','和邻居告别','把关系留在人情里。','羁绊+ · 恢复')]},
{id:'warning',stage:['中年','晚年'],weight:10,when:s=>s.lifeLimit-age()<=12,title:'寿限将至',text:()=>`你开始更频繁地想起年龄。镜子里的人比记忆里老了一些，楼梯也比从前更长。${world().beliefs||'这里的人对生死有自己的说法。'} 续命药的价格写在商店最显眼的位置，像一道不算温柔的门。`,choices:[c('rest','把身体养好','先活得舒服一点。','恢复 · 健康+'),c('work','再挣一笔','为下一颗药多留一点余地。','收入 · 消耗'),c('social','把重要的话说完','有些告别不能等到最后。','羁绊+ · 重要度+')]},
{id:'crisis',stage:['青年','壮年','中年','晚年'],weight:8,when:s=>s.importance>=25,title:'地方危机',text:()=>`${world().risks||'一场突发危机'}波及了你所在的街区。人们看向那些看起来能做决定的人，而你已经被卷进其中。${factionName(1)}的人也在暗中观察。`,choices:[c('explore','去最危险的地方','解决问题，也让自己被记住。','重要度+ · 风险'),c('social','组织邻里互助','不靠英雄，靠一群普通人。','羁绊+ · 声望+'),c('work','趁乱多接活','危机也是生计。','收入 · 重要度-')]},
{id:'merchant',stage:['壮年','中年'],weight:7,when:s=>s.stats.智识>=7,title:'一笔真正的生意',text:()=>`有人愿意让你参股一桩跨地区的买卖。对方说得很有道理，账目也做得漂亮，但你注意到合同里有一处没有写清楚的交货地点。${world().economy||''}`,choices:[c('trade','签下合同','用本金博一次更大的利润。','经商 · 有风险'),c('study','先查清底细','花时间验证对方和货物。','智识+ · 稳健'),c('social','找个可靠的人合伙','把风险分给值得信任的人。','羁绊+ · 收益分成')]},
{id:'inheritance',stage:['中年','晚年'],weight:6,title:'家里的旧东西',text:()=>`你整理旧物时翻出一件不属于自己的东西：一张地契、一枚徽记，或一封没有寄出的信。它指向${world().name}某个你从未认真看过的地方。你忽然意识到，普通人的一生也会留下别人需要继承的东西。`,choices:[c('study','弄清它的来历','把家族与地方的历史接上。','智识+ · 重要度+'),c('social','交给可信的人','有些东西不该独自保管。','羁绊+ · 声望+'),c('rest','先收起来','等有勇气时再面对。','恢复 · 无收益')]},
{id:'wild',stage:['少年','青年','壮年'],weight:6,title:'远方的召唤',text:()=>`一条没有在地图上标出的路出现在你面前。有人说那条路通向机会，也有人说去过的人再没有回来。${world().space||''} 你站在路口，听见风把远处的声响送过来。`,choices:[c('explore','走进去','去看看到底有什么。','探索 · 重要度+'),c('work','回去工作','生活比冒险更需要人。','收入 · 稳健'),c('rest','在路口坐一会','先想清楚自己为什么出发。','恢复 · 机缘+')]},
{id:'patron',stage:['壮年','中年','晚年'],weight:6,when:s=>s.importance>=50,title:'来自上层的邀请',text:()=>`${factionName(0)}向你递来一份邀请。条件很好，代价是你要在某些事情上闭嘴。邀请你的人没有威胁，只把茶杯轻轻放下，等你回答。`,choices:[c('social','接受合作','借他们的资源做自己的事。','羁绊+ · 重要度+'),c('study','先看清条款','不急着答应，先弄懂规则。','智识+ · 稳健'),c('explore','拒绝并离开','有些路不能靠别人铺。','风险 · 重要度+')]},
{id:'quiet',stage:['少年','青年','壮年','中年','晚年'],weight:10,title:'没有大事发生的一年',text:()=>`这一年没有传奇。你做饭、工作、和熟人打招呼，偶尔在夜里想起自己曾经想去的地方。${world().name}仍在运转，而你在其中过着一段普通得几乎不会被记住的日子。`,choices:[c('rest','认真休息','身体是普通人最诚实的资产。','恢复 · 健康+'),c('work','把日子过稳','多一点积蓄，少一点幻想。','收入 · 声望+'),c('social','去看一个朋友','普通日子也需要见证者。','羁绊+ · 恢复')]},
{id:'rift',stage:['青年','壮年','中年','晚年'],weight:7,title:'世界规则的裂缝',text:()=>`你在${world().locations?.[state.location]?.name||'当地'}发现一处不合常理的现象：${world().worldAxis||world().time||'时间与空间在这里并不完全遵守常识。'} 它没有立刻伤害你，却让你意识到，这个世界比表面看起来更复杂。`,choices:[c('study','记录并研究','把异常变成可理解的知识。','智识+ · 重要度+'),c('explore','深入裂缝','亲自走进去看看。','探索 · 风险'),c('rest','离开并保守秘密','有些知识不该轻易传播。','恢复 · 无收益')]},
{id:'pill',stage:['壮年','中年','晚年'],weight:7,when:s=>s.pills>=1,title:'续命之后',text:()=>`服下续命药后，你并没有立刻变得年轻。身体仍在变老，只是终点被推远了一些。${world().beliefs||''} 你开始想：多出来的十年，究竟应该用来做什么？`,choices:[c('rest','慢慢生活','把多出来的时间还给自己。','恢复 · 健康+'),c('study','研究寿命的规则','弄清药性与代价。','智识+ · 重要度+'),c('social','陪伴重要的人','时间有限，关系也有限。','羁绊+ · 恢复')]},
{id:'old',stage:['晚年'],weight:12,title:'晚年的选择',text:()=>`你老了。${world().dailyLife||''} 年轻时以为重要的东西，现在看起来有些轻；而一些微不足道的瞬间，反而记得很清楚。你还有几年，或者十几年。`,choices:[c('rest','安静地过','不再追赶什么。','恢复 · 健康+'),c('social','把故事讲给后来的人','让他们知道这里曾经发生过什么。','羁绊+ · 重要度+'),c('study','留下记录','把一生的经验写下来。','智识+ · 重要度+')]},
{id:'last',stage:['中年','晚年'],weight:10,when:s=>s.lifeLimit-age()<=3,title:'最后一扇门',text:()=>`医生或当地的长者没有说得太明白，但你知道时间不多了。续命药还在商店里，价格依旧冷漠。你回望自己的一生：${state.events.length}个被记住的选择，${state.bond}点人与人之间的牵绊。`,choices:[c('rest','接受它','把最后的时间留给自己。','恢复 · 平静'),c('social','和所有人告别','把未说完的话说完。','羁绊+ · 重要度+'),c('work','再挣一点','也许还能买到下一颗药。','收入 · 健康风险')]}
];
function worldRandomEvent(){const w=world(),loc=w.locations?.[state.location]?.name||'街区';const faction=factionName(0);const risk=w.risks||'一场突发麻烦';const goods=w.goods?.[Math.floor(Math.random()*Math.max(1,w.goods.length))]||'一批货物';const templates=[
{title:'街上来了一笔新买卖',text:`${loc}的市面忽然活跃起来。有人拿出${goods}，说能赶上这一季的行情；${faction}的人却在旁边盯着，想知道谁会先出手。`,choices:[c('trade','吃下这批货','用本金赌一次行情。','经商 · 有亏损风险',{flag:'local_deal'}),c('study','先查清来路','弄明白货和买家到底是谁。','智识+ · 稳健'),c('social','拉一个熟人合伙','把风险分给彼此。','羁绊+ · 分成')]},
{title:'一场没写进文书的争执',text:`${loc}两户人家为一件旧事争执起来。${w.political||'当地管事的人'}不愿插手，围观者却都在等一个能说话的人。你看见其中一方手里攥着${goods}的凭据。`,choices:[c('social','先把人劝开','别让事情在街上失控。','羁绊+ · 声望+'),c('study','按规矩查凭据','把旧账翻到明面上。','智识+ · 重要度+'),c('rest','不掺和','有些麻烦不属于你。','恢复 · 无收益')]},
{title:'风里传来的坏消息',text:`${risk}的消息从${loc}外面传来。${faction}开始封路，普通人忙着囤积${w.goods?.[0]||'粮食'}。你手里有一点点积蓄，也有一点不确定的消息。`,choices:[c('explore','去外面看看','亲自确认消息真假。','探索 · 风险'),c('work','先把手头的活干完','日子总还要过。','收入 · 稳健'),c('social','和邻居互通消息','一群普通人比一个人可靠。','羁绊+ · 情报')]},
{title:'旧地方，新规矩',text:`你回到${loc}，发现${w.space||'街道与门牌'}又变了一点。${faction}贴出新告示，旧的通行方式不再作数。有人抱怨，有人已经开始找新的路。`,choices:[c('study','读懂新告示','弄清楚规则再说。','智识+ · 重要度+'),c('explore','试一条新路','绕开旧地图的限制。','探索 · 机缘+'),c('social','问问老住户','他们知道哪里还能走。','羁绊+ · 情报')]}
];return templates[Math.floor(Math.random()*templates.length)];}
function stageOk(ev){return !ev.stage||ev.stage.includes(stage());}
function nextLocalEvent(initial=false){const e=effect();const recent=state.recentEvents.slice(-4);let pool=EVENTS.filter(ev=>stageOk(ev)&&!recent.includes(ev.id)&&(!ev.when||ev.when(state)));if(!pool.length)pool=EVENTS.filter(ev=>stageOk(ev));if(!pool.length)pool=EVENTS;const weighted=[];for(const ev of pool){const w=Math.max(1,(ev.weight||5)+(has('watcher')?1:0));for(let i=0;i<w;i++)weighted.push(ev);}let ev=weighted[Math.floor(Math.random()*weighted.length)];if(state.events.length>0&&state.events.length%3===0){ev={id:'dynamic_'+Date.now(),stage:['青年','壮年','中年','晚年'],weight:1,...worldRandomEvent()};}else if(state.events.length>0&&state.events.length%4===0){ev={id:'world_rift',stage:['青年','壮年','中年','晚年'],weight:1,title:`${world().theme||'此世'}的裂缝`,text:()=>`${world().risks||'世界的规则正在松动。'}。 ${factionName(0)}与${factionName(1)}之间的冲突，终于波及到你所在的${world().locations?.[state.location]?.name||'街区'}。你无法再只做一个旁观者。`,choices:[c('study','分析规则','从混乱中找出可利用的秩序。','智识+ · 重要度+'),c('social','保护身边的人','先把具体的人照顾好。','羁绊+ · 声望+'),c('explore','进入冲突中心','去改变更大的局面。','重要度+ · 风险') ]};}
const choices=ev.choices.filter(ch=>!ch.require||ch.require(state));return {id:ev.id,title:ev.title,text:cleanText(typeof ev.text==='function'?ev.text():ev.text),choices:choices.length?choices:ev.choices.slice(0,3),visual:`${world().name}，${state.identity}，${age()}岁，${ev.title}，原创二维电影感画面，青蓝与暖金，无文字`};}
function advance(days){const oldYear=cal().year,oldMonthAbs=Math.floor(state.days/30);state.days+=Math.max(1,Math.round(days*effect().time));const newMonthAbs=Math.floor(state.days/30);const months=Math.max(0,newMonthAbs-oldMonthAbs);if(months>0){const cost=Math.floor(LIVING_MONTH*months*effect().cost);state.coins=Math.max(0,state.coins-cost);state.chronicle.unshift({year:cal().year,title:'生活结算',detail:`${months}个月饮食、住宿与日常支出合计${cost}${world().currency}。`});}if(cal().year!==oldYear){if(age()>60)state.health=Math.max(1,state.health-4);state.chronicle.unshift({year:cal().year,title:`${age()}岁`,detail:`进入${stage()}。寿限${state.lifeLimit}岁。`});if(state.lifeLimit-age()<=5)toast(`寿命提醒：距自然寿限还有${state.lifeLimit-age()}年`);}if(age()>=state.lifeLimit&&!state.deceased){state.deceased=true;state.health=0;state.chronicle.unshift({year:cal().year,title:'此生谢幕',detail:`你在${world().name}走完了自己的一生。`});checkAchievements();}}
function outcomeText(choice,income,delta,bonus){const base={work:`你把这一年交给了工作。工钱不算丰厚，但足以让你继续留在${world().name}。`,study:`你花时间整理知识，渐渐看懂了这个世界的运行方式。`,social:`你与一个人建立了更深的联系。关系不会立刻变成钱，却会在未来某个时刻回来。`,explore:`你走进了陌生区域。危险是真的，收获也是真的。`,trade:`你完成了一笔生意。账本上的数字让你对这个世界多了一点掌控感。`,rest:`你停下来休息。生活没有因此变好，但身体和心都缓了一口气。`}[choice];return `${base}${income>0?`\n\n收入：${income} ${world().currency}。`:''}${bonus?.flag?`\n\n新的标记：${bonus.flag}。`:''}`;}
function applyChoice(choiceId,eventChoice={}){if(state.busy||state.deceased)return;const e=effect(),s=state.stats;let income=0,delta={},days=360,bonus=eventChoice.bonus||{};const beforeCoins=state.coins;
switch(choiceId){case 'work':income=annualIncome();state.energy=Math.max(0,state.energy-30);state.reputation+=8;if(Math.random()<.35)delta[e.workStat]=1;break;case 'study':income=Math.floor(900*e.income);delta.智识=Math.random()<.8?1:0;state.importance=Math.min(100,state.importance+Math.floor(3*e.event));state.energy=Math.max(0,state.energy-18);break;case 'social':state.bond=Math.min(100,state.bond+Math.floor(13*e.bond));delta.魅力=Math.random()<.35?1:0;state.reputation+=5;state.energy=Math.max(0,state.energy-12);days=180;break;case 'explore':{const success=Math.random()<.55+s.机缘*.025+s.智识*.012;income=Math.floor((success?14000:1800)*e.income);state.importance=Math.min(100,state.importance+Math.floor((success?10:3)*e.event));if(!success)state.health=Math.max(1,state.health-Math.floor(24*e.risk));state.energy=Math.max(0,state.energy-38*e.energy);delta.机缘=Math.random()<.2?1:0;break;}case 'trade':{const capital=Math.max(0,Math.min(state.coins,Math.floor(state.coins*.35)));const profit=Math.floor((4000+s.智识*800+s.机缘*450)*e.trade*e.income);if(Math.random()<.25){income=-Math.min(capital,Math.floor(profit*.7));}else income=profit;state.energy=Math.max(0,state.energy-22);days=300;delta.智识=Math.random()<.15?1:0;break;}case 'rest':state.health=Math.min(100,state.health+Math.floor(30*e.healthRegen));state.energy=Math.min(100,state.energy+55);days=120;break;default:days=120;}
if(bonus.coins)income+=bonus.coins;if(bonus.health)state.health=Math.max(1,Math.min(100,state.health+bonus.health));if(bonus.energy)state.energy=Math.max(0,Math.min(100,state.energy+bonus.energy));if(bonus.importance)state.importance=Math.min(100,state.importance+Math.floor(bonus.importance*e.event));if(bonus.bond)state.bond=Math.min(100,state.bond+Math.floor(bonus.bond*e.bond));if(bonus.stats)for(const k in bonus.stats)delta[k]=(delta[k]||0)+bonus.stats[k];if(bonus.flag&&!state.flags.includes(bonus.flag))state.flags.push(bonus.flag);if(bonus.move)state.location=(state.location+bonus.move+4)%4;
state.coins=Math.max(0,state.coins+income);for(const k in delta)state.stats[k]=Math.max(1,Math.min(20,state.stats[k]+delta[k]));if(state.career<5&&state.reputation>=state.career*60){state.career++;state.occupation=['学徒','熟练工','本地行家','行业名宿','一方领袖'][state.career-1];toast(`职业晋升：${state.occupation}`);}advance(days);state.counts[choiceId]=(state.counts[choiceId]||0)+1;state.recentEvents.push(state.currentEvent?.id);if(state.recentEvents.length>8)state.recentEvents.shift();const outcome=outcomeText(choiceId,income,delta,bonus);state.lastOutcome={text:outcome,income,delta};const entry={year:cal().year,age:age(),title:state.currentEvent?.title||'人生选择',choice:CHOICES.find(x=>x.id===choiceId)?.title||choiceId,text:outcome,income,delta,date:dateText()};state.events.push(entry);state.chronicle.unshift({year:cal().year,title:entry.title,detail:outcome});state.artUrl='';checkEvolutions();checkAchievements();state.result={title:entry.title,choice:entry.choice,text:outcome,income,delta,date:entry.date,words:pickEnglish(choiceId+'-'+state.events.length+'-'+state.worldIndex)};save();render();}
function choose(id){if(!state.currentEvent||state.busy||state.result)return;const c=state.currentEvent.choices.find(x=>x.id===id)||CHOICES.find(x=>x.id===id);if(!c)return;applyChoice(id,c);}
function continueAfterResult(){if(!state.result||state.busy)return;if(state.ai&&state.apiKey){generateNextEvent();}else{state.result=null;state.lastOutcome=null;state.currentEvent=nextLocalEvent();save();render();}}
function play(){return `<div class="view" style="padding:0">${lifeNav()}${page==='event'?eventPage():page==='life'?lifePage():page==='relation'?relationPage():page==='map'?mapPage():page==='shop'?shopPage():chroniclePage()}</div>`;}
function lifeNav(){return `<div style="padding:16px 17px 0"><div class="row"><div><b class="cyan">${dateText()}</b><div class="small muted">${stage()} · ${age()}岁 / 寿限${state.lifeLimit}岁 · ${state.occupation}</div></div><div style="text-align:right"><b class="gold mono" style="font-size:22px">${state.coins.toLocaleString()}</b><div class="small muted">${world().currency}</div></div></div>${attrs()}</div><div class="tabs">${[['event','人生事件'],['life','生涯'],['relation','人物'],['map','空间'],['shop','世界商店'],['chronicle','编年史']].map(([k,n])=>`<button class="tab ${page===k?'active':''}" onclick="nav('${k}')">${n}</button>`).join('')}</div>`;}
function nav(p){page=p;render();}
function resultPage(){const r=state.result;return `<div class="view"><div class="eyebrow">THIS YEAR'S OUTCOME</div><h1 class="title" style="font-size:24px">${esc(r.title)}</h1><div class="card" style="border-color:#e3bf7455"><span class="eyebrow">你选择了：${esc(r.choice)}</span><p class="small" style="white-space:pre-line;line-height:2">${esc(cleanText(r.text))}</p>${r.income?`<p class="small gold">本世界货币变化：${r.income>0?'+':''}${r.income} ${world().currency}</p>`:''}${Object.entries(r.delta||{}).filter(([,v])=>v).length?`<p class="small cyan">属性：${Object.entries(r.delta).filter(([,v])=>v).map(([k,v])=>`${k}${v>0?'+':''}${v}`).join(' · ')}</p>`:''}</div>${state.english?englishCard(r.words):''}<div class="notice">这一年已经过去。看完结果后，再进入下一幕。</div><button class="btn primary" ${state.busy?'disabled':''} onclick="continueAfterResult()">${state.busy?'世界正在回应…':'确定，进入下一幕 ›'}</button></div>`;}
function eventPage(){const e=state.currentEvent;if(state.deceased)return endingPage();if(state.result)return resultPage();if(!e)return `<div class="view center"><p class="muted">正在连接下一个事件…</p></div>`;return `<div class="view"><div class="row"><span class="eyebrow">${world().name} / ${rank()}级</span><span class="small muted">${stage()} · 第${state.events.length+1}个人生节点</span></div>${state.artUrl?`<img class="portrait" src="${esc(state.artUrl)}" alt="原创事件画像">`:`<img class="portrait" src="${worldArt()}" alt="${esc(world().name)}原创氛围画像">`}<h1 class="title" style="font-size:24px">${esc(e.title)}</h1><div class="story">${esc(cleanText(e.text))}</div><hr class="divider"><p class="eyebrow">你的选择将写入此生</p>${e.choices.map(ch=>`<button class="btn choice" ${state.busy?'disabled':''} onclick="choose('${ch.id}')"><strong>${esc(ch.title||CHOICES.find(x=>x.id===ch.id)?.title||ch.id)}</strong><span>${esc(ch.desc||'')}</span><em>${esc(ch.hint||'')}</em></button>`).join('')}${state.busy?'<p class="cyan center">世界正在回应你的选择……</p>':''}<p class="small muted">${state.ai&&state.apiKey?'DeepSeek根据当前状态生成下一个人生事件；本地引擎校验属性、金钱和时间。':'当前为离线事件模式，可完整游玩。'}</p></div>`;}
function lifePage(){const inc=annualIncome(),cost=annualCost(),net=inc-cost;return `<div class="view"><div class="eyebrow">A LIFE, NOT A SCORE</div><h1 class="title">此生生涯</h1><div class="card"><div class="row"><h3 class="cyan">${world().name}</h3><span class="tag">${world().currency}</span></div><p class="small">${esc(world().theme||world().civilization||'')}</p><p class="small muted">${esc(world().time||'')}</p><button class="btn ghost" onclick="showDossier(${state.worldIndex})">打开十六维世界档案</button></div><div class="card"><div class="row"><h3>${state.occupation} · Lv.${state.career}</h3><span class="tag cyan">声望${state.reputation}</span></div><div class="grid2" style="margin:12px 0"><div><span class="small muted">当前年收入</span><b class="gold" style="display:block">${inc.toLocaleString()}</b></div><div><span class="small muted">年生活成本</span><b class="red" style="display:block">${cost.toLocaleString()}</b></div></div><p class="small muted">年净结余约 ${net.toLocaleString()} ${world().currency}。续命药当前 ${pillPrice().toLocaleString()}，约需 ${pillYears()}。</p><button class="btn" onclick="choose('work')">接下一年的工作 · 收入</button></div><div class="card"><div class="row"><h3>人物羁绊</h3><span class="cyan">${state.bond}/100</span></div><p class="small muted">不是攻略NPC，而是在漫长岁月里相互记得。</p><button class="btn" onclick="choose('social')">用半年走访故友</button></div><div class="card"><h3>四维属性</h3>${Object.entries(state.stats).map(([k,v])=>`<div class="row" style="margin:10px 0"><span>${k}</span><b class="cyan mono">${v}</b></div>`).join('')}<p class="small muted">属性由初始分配、职业和人生事件改变，不靠稀有度无限叠加。</p></div><div class="card"><h3>此生构筑</h3>${state.talents.map(id=>{const t=talent(id);return t?`<p class="small"><b class="${t.r}">${t.name}</b> · ${t.gain}<br><span class="red">${t.cost}</span>${t.evolve?`<br><span class="cyan">成长条件：${t.evolve.label}</span>`:''}</p>`:'';}).join('')}</div><div class="card"><div class="row"><h3>人生痕迹</h3><span class="tag">${state.flags.length}个标记</span></div><p class="small muted">${state.flags.length?state.flags.join(' · '):'还没有形成长期标记。'}</p><p class="small muted">已解锁成就 ${state.achievements.length}/${ACHIEVEMENTS.length}，点击右上角“档”查看轮回记录。</p></div><button class="btn ghost" onclick="settle()">安静度过一年 · 恢复身体</button></div>`;}
function settle(){if(state.deceased)return;state.health=Math.min(100,state.health+20*effect().healthRegen);state.energy=Math.min(100,state.energy+60);advance(360);state.events.push({title:'安静的一年',choice:'休整',text:'你把一年留给了生活。没有赚到钱，但身体和心都恢复了一些。',date:dateText(),year:cal().year});state.chronicle.unshift({year:cal().year,title:'安静的一年',detail:'生活成本已结算，健康与精力恢复。'});save();render();}
function locs(){const raw=world().locations||[];const fallback=['平民聚居地','地方集市','边境古道','权力中枢'].map(n=>({name:n,role:'熟悉的人、工作与地方规则各不相同。'}));if(!raw.length)return fallback;return raw.map(l=>typeof l==='string'?{name:l,role:'这里的日常、人物与机会各不相同。'}:l);}
function relationPage(){const rs=state.relationships||[];return `<div class="view"><div class="eyebrow">PEOPLE, NOT RESOURCES</div><h1 class="title">人物</h1><p class="subtitle">工作之外，你也会遇到一些人。关系不是数值奖励，而是你愿意把时间交给谁。</p>${state.relationNote?`<div class="notice">${esc(state.relationNote)}</div>`:''}<div class="card"><div class="row"><h3>身边的人</h3><span class="tag">${rs.length}人</span></div><p class="small muted">${relationLine()}</p>${rs.length<6?`<button class="btn ghost" onclick="meetSomeone()">认识一个新的人 · 100 ${world().currency} + 3个月</button>`:''}</div>${rs.map(r=>{const st=relationStage(r);return `<div class="card"><div class="row"><div><h3 class="cyan">${esc(r.name)}</h3><span class="small muted">${esc(r.role)} · ${esc(st)}</span></div><span class="tag ${st==='恋人'?'gold':st==='知己'?'cyan':''}">${esc(st)}</span></div><p class="small">${esc(r.trait)}</p><p class="small muted">心愿：${esc(r.desire)}</p><div class="statline" style="margin-top:12px"><span>好感 ${r.affinity}</span><span>信任 ${r.trust}</span></div><div class="bar"><i style="width:${r.affinity}%;background:var(--cyan)"></i></div><div class="bar" style="margin-top:4px"><i style="width:${r.trust}%;background:var(--gold)"></i></div><div class="row" style="gap:8px;margin-top:12px"><button class="btn ghost" style="width:auto" onclick="talkTo('${r.id}')">交谈 · 3个月</button><button class="btn ghost" style="width:auto" onclick="shareWith('${r.id}')">共同经历 · 半年</button>${relationStage(r)==='知己'?`<button class="btn" style="width:auto" onclick="confess('${r.id}')">表明心意</button>`:''}</div></div>`;}).join('')}<div class="notice">关系会随时间沉淀：交谈增加好感与信任，共同经历更快；达到知己后，才可能出现“恋人”这一层。</div></div>`;}
function mapPage(){const list=locs();return `<div class="view"><h1 class="title">空间与旅途</h1><p class="subtitle">${esc(world().space||'')}</p>${list.map((l,i)=>`<div class="card"><div class="row"><h3 class="${i===state.location?'cyan':''}">${esc(l.name)}</h3>${i===state.location?'<span class="tag cyan">当前</span>':''}</div><p class="small muted">${esc(l.role||'这里的日常、人物与机会各不相同。')}</p>${i!==state.location?`<button class="btn" onclick="travel(${i})">旅行 ${Math.abs(i-state.location)} 年 · ${Math.max(100,Math.floor(1500*effect().travel))}${world().currency}</button>`:''}</div>`).join('')}<div class="notice">旅行会真实消耗年份和盘缠。远方的机会更大，但不是免费的。</div></div>`;}
function travel(i){const cost=Math.max(100,Math.floor(1500*effect().travel));if(state.coins<cost)return toast('盘缠不足，先攒一点钱');state.coins-=cost;advance(Math.abs(i-state.location)*360);state.location=i;const dest=locs()[i]?.name||'新的地区';state.chronicle.unshift({year:cal().year,title:'一次远行',detail:`来到${dest}，付出${cost}${world().currency}。`});save();render();toast(`抵达${dest}`);}
function shopPage(){const pill=pillPrice(),change=(rate()/rate(-1)-1)*100;return `<div class="view"><h1 class="title">世界商店</h1><p class="subtitle">1续命标准券 = ${rate().toFixed(2)}${world().currency} · <span class="${change>=0?'red':'cyan'}">${change>=0?'+':''}${change.toFixed(2)}%</span></p><div class="card"><div class="row"><h3 class="gold">续命药</h3><b class="gold">${pill.toLocaleString()}</b></div><p class="small muted">寿限+10年，不治愈伤病。已服${state.pills}颗，下一颗基础价×1.8。按当前净收入约需 ${pillYears()}。这不是几天能刷出来的数字。</p><button class="btn" ${state.coins<pill?'disabled':''} onclick="buyLife(${pill})">购买并服用 · 延寿10年</button></div>${[['伤药',3000,'恢复35生命'],['旅行补给',1200,'恢复45精力'],['地方情报',6000,'重要度+4']].map(([n,p,d])=>`<div class="card"><div class="row"><h3>${n}</h3><b class="gold">${price(p).toLocaleString()}</b></div><p class="small muted">${d}</p><button class="btn" ${state.coins<price(p)?'disabled':''} onclick="buyItem('${n}',${price(p)})">购买</button></div>`).join('')}<div class="card"><h3>本世界特产</h3>${(world().goods||[]).map((g,i)=>`<div class="row" style="margin:13px 0"><span>${esc(g)}</span><button class="btn ghost" style="width:auto" onclick="buySpecial('${esc(g)}',${price(8000+i*2500)})">${price(8000+i*2500).toLocaleString()}</button></div>`).join('')}</div><div class="notice">货币、商品与行囊仅限当前世界，不跨世界兑换。续命药是长期经营目标，不是早期奖励。</div></div>`;}
function buyLife(p){if(state.coins<p)return;state.coins-=p;state.pills++;state.lifeLimit+=10;state.chronicle.unshift({year:cal().year,title:'向时间借来十年',detail:`寿限延长至${state.lifeLimit}岁，支付${p}${world().currency}。`});checkAchievements();save();render();toast('寿限+10年');}
function buyItem(n,p){if(state.coins<p)return;state.coins-=p;if(n==='伤药')state.health=Math.min(100,state.health+35);if(n==='旅行补给')state.energy=Math.min(100,state.energy+45);if(n==='地方情报')state.importance=Math.min(100,state.importance+4);save();render();}
function buySpecial(n,p){if(state.coins<p)return toast('货币不足');state.coins-=p;state.inventory[n]=(state.inventory[n]||0)+1;checkAchievements();save();render();toast(`${n}已放入本世界行囊`);}
function chroniclePage(){return `<div class="view"><h1 class="title">个人编年史</h1><p class="subtitle">你在这里真实度过的每一年，都不会被下一场冒险抹去。</p><div class="timeline">${state.chronicle.map(ev=>`<div class="event"><span class="eyebrow">第${ev.year}年</span><h3>${esc(ev.title)}</h3><p class="small muted">${esc(ev.detail)}</p></div>`).join('')||'<p class="muted">尚无记录。</p>'}</div></div>`;}
const ACHIEVEMENTS=[
{id:'first_pay',name:'第一次靠自己吃饭',desc:'完成第一次工作',when:s=>s.counts.work>=1},
{id:'savings',name:'第一笔积蓄',desc:'积蓄达到10,000本世界币',when:s=>s.coins>=10000},
{id:'rich',name:'一方富户',desc:'积蓄达到100,000本世界币',when:s=>s.coins>=100000},
{id:'career5',name:'行业名宿',desc:'职业达到5级',when:s=>s.career>=5},
{id:'bond80',name:'有人记得你',desc:'羁绊达到80',when:s=>s.bond>=80},
{id:'explorer',name:'走过无人处',desc:'探索10次',when:s=>s.counts.explore>=10},
{id:'scholar',name:'穷理者',desc:'智识达到12',when:s=>s.stats.智识>=12},
{id:'long',name:'向天借命',desc:'服用3颗续命药',when:s=>s.pills>=3},
{id:'survivor',name:'长寿者',desc:'活到80岁',when:s=>age()>=80},
{id:'legend',name:'世界史诗',desc:'世界重要度达到100',when:s=>s.importance>=100},
{id:'allround',name:'四全之人',desc:'四维属性全部达到8',when:s=>Object.values(s.stats).every(v=>v>=8)},
{id:'collector',name:'行囊收藏家',desc:'收集5种本世界特产',when:s=>Object.keys(s.inventory).length>=5},
{id:'redeemed',name:'还清旧债',desc:'从预支传奇走到还债之人',when:s=>has('redeemed')},
{id:'soulmate',name:'遇见知己',desc:'有人真正理解你',when:s=>(s.relationships||[]).some(r=>relationStage(r)==='知己'||relationStage(r)==='恋人')},
{id:'lover',name:'有人同行',desc:'与某个人确认恋爱关系',when:s=>(s.relationships||[]).some(r=>r.romance)},
{id:'network',name:'小小的世界',desc:'与3个人达到好友以上',when:s=>(s.relationships||[]).filter(r=>['好友','知己','恋人'].includes(relationStage(r))).length>=3},
{id:'english10',name:'另一种语言',desc:'一生中记住10个英语词/短语',when:s=>s.englishThisLife.length>=10},
{id:'quiet',name:'完整的一生',desc:'自然活到寿限',when:s=>s.deceased&&age()>=s.lifeLimit}
];
function checkAchievements(){for(const a of ACHIEVEMENTS){if(!state.achievements.includes(a.id)&&a.when(state)){state.achievements.push(a.id);if(!meta.achievements.includes(a.id))meta.achievements.push(a.id);toast(`成就解锁：${a.name}`);saveMeta();}}}
function checkEvolutions(){for(const id of [...state.talents]){const t=talent(id);if(t?.evolve&&t.evolve.when(state)&&!state.talents.includes(t.evolve.into)){state.talents=state.talents.map(x=>x===id?t.evolve.into:x);const nt=talent(t.evolve.into);state.chronicle.unshift({year:cal().year,title:`天赋成长：${nt?.name||t.evolve.into}`,detail:`${t.name}在漫长生活中发生了变化。`});toast(`天赋成长：${nt?.name||t.evolve.into}`);}}}
function score(){const base=Object.values(state.stats).reduce((a,b)=>a+b,0)*15+state.importance*12+state.bond*5+state.career*30+Math.min(100,Math.floor(state.coins/1000))+age()*2+state.pills*50+state.achievements.length*20+(state.relationships||[]).reduce((a,r)=>a+r.affinity+r.trust,0)+state.englishThisLife.length*8;return Math.max(0,base);}
function endingTitle(){if(state.importance>=100&&state.pills>=2)return '驻世史诗';if(state.importance>=100)return '一域传奇';if((state.relationships||[]).some(r=>r.romance))return '有人同行的一生';if((state.relationships||[]).some(r=>relationStage(r)==='知己'))return '被理解的灵魂';if(has('redeemed'))return '还债之人';if(state.pills>=3)return '与时间讨价还价的人';if(state.bond>=75)return '被许多人记住的人';if(state.career>=5)return '行业名宿';if(state.coins>=100000)return '富甲一方';if(age()>=80)return '安度的长寿者';if(state.counts.explore>=8)return '远行者';return '普通而完整的一生';}
function endingPage(){const title=endingTitle(),sc=score();return `<div class="view"><div class="eyebrow">THE END OF A LIFE</div><h1 class="title">此生谢幕</h1><div class="card center"><div class="logo" style="font-size:30px">${esc(title)}</div><p class="story">${esc(state.name)} · ${world().name}<br>${age()}岁 · ${state.occupation} · ${rank()}级<br><br>你在这片世界留下了 ${state.events.length} 个被记住的选择。<br>有人记得你，世界也因你改变了一点点。</p><div class="row" style="justify-content:center;gap:24px;margin-top:15px"><div><span class="small muted">人生评分</span><b class="gold" style="display:block;font:700 28px var(--mono)">${sc}</b></div><div><span class="small muted">成就</span><b class="cyan" style="display:block;font:700 28px var(--mono)">${state.achievements.length}/${ACHIEVEMENTS.length}</b></div></div></div><div class="card"><h3>这一生</h3>${state.achievements.map(id=>{const a=ACHIEVEMENTS.find(x=>x.id===id);return a?`<p class="small">✓ ${a.name} · ${a.desc}</p>`:'';}).join('')||'<p class="small muted">没有解锁成就，但你仍然活过。</p>'}</div><div class="card" style="border-color:#77b7fa44"><div class="row"><h3 class="cyan">English Harvest</h3><span class="tag">${state.englishThisLife.length} 个</span></div><p class="small muted">这一生你记住的英语，已经收进永久词库。累计 ${meta.english.length} 个。</p>${state.englishThisLife.map(id=>{const w=ENGLISH_PACK.find(x=>x.id===id);return w?`<p class="small"><b style="color:#77b7fa">${w.word}</b> · ${w.zh}</p>`:'';}).join('')||'<p class="small muted">这一生没有点记住任何词。下一次可以慢慢来。</p>'}</div><button class="btn primary" onclick="finish()">把这一生载入轮回档案</button></div>`;}
function finish(){if(!state.runRecorded){meta.runs.unshift({date:new Date().toLocaleString('zh-CN'),name:state.name,world:world().name,age:age(),title:endingTitle(),score:score(),achievements:[...state.achievements],english:[...state.englishThisLife]});if(meta.runs.length>30)meta.runs.length=30;state.runRecorded=true;saveMeta();}resetLife();state.screen='setup';setupStep=0;state.worldIndex=-1;state.talents=[];state.pools=[];state.roll=0;save();render();toast('此生已载入轮回档案');}
function showMeta(){$('#app').insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div><div class="row"><h2>轮回档案</h2><button class="btn ghost" style="width:auto" onclick="$('#modal').remove()">关闭</button></div><p class="small muted">共 ${meta.runs.length} 次人生 · 永久成就 ${meta.achievements.length}/${ACHIEVEMENTS.length}</p>${meta.runs.length?meta.runs.map(r=>`<div class="card"><div class="row"><b class="cyan">${esc(r.title)}</b><span class="gold">${r.score}</span></div><p class="small muted">${esc(r.name)} · ${esc(r.world)} · ${r.age}岁 · ${r.achievements.length}成就<br>${esc(r.date)}</p></div>`).join(''):'<p class="small muted">还没有完成的人生。先去活一次吧。</p>'}<hr class="divider"><h3>永久成就</h3>${ACHIEVEMENTS.map(a=>`<p class="small ${meta.achievements.includes(a.id)?'cyan':'muted'}">${meta.achievements.includes(a.id)?'✓':'○'} ${a.name} · ${a.desc}</p>`).join('')}</div></div>`);}
function showDossier(i){const w=WORLDS[i];if(!w)return;const deviations=[w.worldAxis,w.time,w.space].filter(Boolean);const chain=[['经济','economy'],['阶层','stratification'],['日常','dailyLife'],['家庭','family'],['信仰','beliefs'],['秩序','order'],['审美','aesthetics']].filter(([,k])=>w[k]);const dims=[['政治格局','political'],['人口族群','demographics'],['经济商贸','economy'],['科技','tech'],['文艺文化','arts'],['阶层关系','stratification'],['日常生活','dailyLife'],['婚恋家庭','family'],['信仰民俗','beliefs'],['思想思潮','intellectual'],['集体心理','psychology'],['治安秩序','order'],['信息传播','information'],['生存风险','risks'],['时代审美','aesthetics'],['生态自然','ecology']];$('#app').insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div><div class="row"><div><span class="world-number">WORLD ${String(i+1).padStart(2,'0')}</span><h2 class="cyan">${esc(w.name)}</h2></div><button class="btn ghost" style="width:auto" onclick="$('#modal').remove()">关闭</button></div><p class="small gold">${esc(w.theme||w.civilization||'')}</p><p class="small muted">${esc(w.era||'')} · 货币 ${esc(w.currency)}</p><p class="small muted">文化身份：${esc(w.culturalIdentity||w.identity||'')}</p><p class="small">${esc(w.worldAxis||'')}</p><div class="divider"></div><p class="eyebrow">世界如何度过一生</p><p class="small"><b class="cyan">幼年与家庭</b> · ${esc(w.family||w.dailyLife||'')}</p><p class="small"><b class="cyan">求学与技艺</b> · ${esc(w.tech||w.arts||'')}</p><p class="small"><b class="cyan">成年与生计</b> · ${esc(w.economy||w.stratification||'')}</p><p class="small"><b class="cyan">晚年与死亡</b> · ${esc(w.beliefs||w.risks||'')}</p><div class="divider"></div><p class="eyebrow">核心偏离 · 三条以内</p>${deviations.map((x,j)=>`<p class="small"><b class="gold">${j+1}.</b> ${esc(x)}</p>`).join('')}<p class="eyebrow" style="margin-top:12px">七层后果链</p>${chain.map(([n,k],j)=>`<p class="small"><b class="cyan">${j+1} ${n}</b> · ${esc(w[k])}</p>`).join('')}<div class="divider"></div><div class="list">${dims.map(([n,k])=>w[k]?`<div><b class="cyan small">${n}</b><p class="small muted" style="margin:3px 0 10px">${esc(w[k])}</p></div>`:'').join('')}</div>${w.factions?`<p class="small"><b class="cyan">主要势力</b>：${w.factions.map(esc).join(' · ')}</p>`:''}${w.timeline?`<div class="divider"></div><h3>关键时间轴</h3>${w.timeline.map(t=>`<p class="small"><b class="gold">${esc(t.year)}</b> · ${esc(t.event)}</p>`).join('')}`:''}${w.locations?`<div class="divider"></div><h3>可去之处</h3>${w.locations.map(l=>`<p class="small"><b class="cyan">${esc(l.name)}</b> · ${esc(l.role)}</p>`).join('')}`:''}</div></div>`);}
function showGuide(){$('#app').insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div><h2>此世生存指南</h2><p class="small">四维属性影响事件、工作和风险。职业、羁绊和事件会持续成长；每次主要选择通常消耗一年。</p><p class="small">天赋不是稀有度排名：普通天赋有稳定经营路线，SSS/UR有寿限、收入、健康或生活成本代价，并且存在互斥组合。满足条件会成长。</p><p class="small">普通人寿限100岁。续命药120,000本世界币起，之后每颗×1.8，是十年尺度的目标。年生活成本会自动扣除。</p><p class="small">所有进度和接口配置只保存在当前浏览器。清除站点数据会删除存档。</p><button class="btn primary" onclick="$('#modal').remove()">明白了</button></div></div>`);}
function showEnglishBook(){const learned=meta.english.map(id=>ENGLISH_PACK.find(w=>w.id===id)).filter(Boolean);$('#app').insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div><div class="row"><h2>永久英语词库</h2><button class="btn ghost" style="width:auto" onclick="$('#modal').remove()">关闭</button></div><p class="small muted">跨人生保留 · 共 ${learned.length} 个。学习是慢的，不需要一次记完。</p>${learned.length?learned.map(w=>`<div class="card"><p class="small"><b style="color:#77b7fa">${w.word}</b> · ${w.zh}</p><p class="small muted" style="margin:5px 0">${w.ex}</p></div>`).join(''):'<p class="small muted">还没有记住的词。下一次在事件结果页点一下词卡即可。</p>'}</div></div>`);}
function showSettings(){settingsRender();}
function settingsRender(){$('#app').insertAdjacentHTML('beforeend',`<div class="modal" id="modal"><div><h2>本地设置</h2><div class="notice">无云端存档。密钥仅存当前浏览器；请求直接发往接口。DeepSeek不需要Mac或本地代理。</div><label class="small" style="display:flex;gap:10px;align-items:center;margin:12px 0"><input type="checkbox" id="english" ${state.english?'checked':''} style="width:auto"> 每段结算后提供英文回顾（可自行选择读或不读）</label><div class="field"><label>DeepSeek API Key（文本，可选）</label><input id="api" type="password" value="${esc(state.apiKey)}" placeholder="sk-... 不填写则离线游玩"></div><p class="small muted">官方接口：https://api.deepseek.com/v1/chat/completions<br>模型：deepseek-chat。<br>浏览器直连可能受跨域策略影响；失败会自动保留离线事件。</p><div class="field"><label>火山方舟图片API Key（原创画像，可选）</label><input id="imageKey" type="password" value="${esc(state.imageKey)}" placeholder="不填写则使用原创本地剪影"></div><button class="btn" onclick="saveSettings()">保存到本机</button> <button class="btn ghost" onclick="testDeepSeek()">测试文本接口</button><button class="btn ghost" onclick="$('#modal').remove()">关闭</button><hr class="divider"><button class="btn danger" onclick="if(confirm('删除当前浏览器全部进度？')){localStorage.removeItem(KEY);localStorage.removeItem(META_KEY);location.reload()}">删除本地进度</button></div></div>`);}
function saveSettings(){state.apiKey=$('#api').value.trim();state.imageKey=$('#imageKey').value.trim();const en=$('#english');if(en)state.english=en.checked;save();$('#modal').remove();render();toast('配置已保存到当前浏览器');}
async function testDeepSeek(){saveSettings();if(!state.apiKey)return toast('请先填写DeepSeek密钥');try{const r=await fetch('https://api.deepseek.com/v1/models',{headers:{Authorization:`Bearer ${state.apiKey}`}});toast(r.ok?'DeepSeek连接成功':'接口拒绝连接，请检查密钥');}catch(e){toast('浏览器直连受限，可继续离线游玩；iOS原生版没有此限制');}}
async function generateNextEvent(){if(state.busy||state.deceased)return;state.busy=true;render();try{const w=world();const recent=state.events.slice(-5).map(e=>e.title+'/'+e.choice).join('；');const prompt=`你是中文人生模拟器，主持一个普通人一生中的一年。世界：${w.name}；主题：${w.theme||w.civilization}；文明矛盾：${w.civilization}；政治：${w.political||''}；经济：${w.economy||''}；风险：${w.risks||''}；时间规则：${w.time||''}；空间规则：${w.space||''}。角色：${state.name}，${age()}岁，${stage()}，${state.identity}，职业${state.occupation}，属性${JSON.stringify(state.stats)}，天赋${state.talents.join(',')}，羁绊${state.bond}，重要度${state.importance}，人物关系${(state.relationships||[]).map(r=>`${r.name}(${relationStage(r)})`).join('、')}，已知标记${state.flags.join(',')}，近期事件${recent}。生成一个符合年龄、身份和本世界文明的不重复事件，有具体矛盾和取舍，但不能突然无敌或改变世界规则。严格只返回JSON：{"title":"不超过18字","text":"80至160字第二人称剧情","choices":[{"id":"work|study|social|explore|trade|rest之一","title":"选择名","desc":"具体行动","hint":"风险或方向"}],"visual":"原创画面中文描述"}。3个选项，id必须从给定列表选。`;const r=await fetch('https://api.deepseek.com/v1/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.apiKey}`},body:JSON.stringify({model:'deepseek-chat',messages:[{role:'user',content:prompt}],temperature:.85,response_format:{type:'json_object'}})});if(!r.ok)throw Error('API');const data=await r.json(),parsed=JSON.parse(data.choices[0].message.content);if(!parsed.title||!parsed.text||!Array.isArray(parsed.choices))throw Error('schema');const valid=parsed.choices.filter(ch=>CHOICES.some(x=>x.id===ch.id)).slice(0,4);if(valid.length<2)throw Error('choices');state.result=null;state.lastOutcome=null;state.currentEvent={...parsed,choices:valid};save();if(state.imageKey)generateImage(parsed.visual||state.currentEvent.title);}catch(e){toast('AI暂不可用，已切换到本地事件');state.result=null;state.lastOutcome=null;state.currentEvent=nextLocalEvent();}finally{state.busy=false;save();render();}}
async function generateImage(visual){try{const prompt=`原创角色与场景，不使用已有作品角色。${world().name}，${state.identity}，${age()}岁，${state.appearance}。${visual||''}。${world().visual||''}电影感二维插画，青蓝阴影与温暖肤色，竖幅，画面无文字。`;const r=await fetch('https://ark.cn-beijing.volces.com/api/v3/images/generations',{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${state.imageKey}`},body:JSON.stringify({model:'doubao-seedream-4-0-250828',prompt,size:'1440x2560',response_format:'url',watermark:false})});if(!r.ok)return;const d=await r.json();if(d.data?.[0]?.url){state.artUrl=d.data[0].url;save();render();}}catch(e){}}
// Lock page zoom and dismiss the keyboard when tapping outside a field.
document.addEventListener('gesturestart', e => e.preventDefault(), {passive:false});
document.addEventListener('touchmove', e => { if (e.touches.length > 1) e.preventDefault(); }, {passive:false});
document.addEventListener('pointerdown', e => {
  if (e.target.closest('input,textarea,select')) return;
  const active = document.activeElement;
  if (active && /^(INPUT|TEXTAREA|SELECT)$/.test(active.tagName)) active.blur();
}, true);
function normalizeWorlds(){for(const w of WORLDS){for(const k of ['civilization','dailyLife','economy','risks','order','space','time','beliefs','tech','worldAxis','theme','political','demographics','arts','stratification','family','intellectual','psychology','information','aesthetics','ecology']){if(typeof w[k]==='string')w[k]=w[k].trim();}}}
normalizeWorlds();load();page='event';render();
